// Build the browser parser bundle. Run via `npm run build:parser` from repo
// root. NOT invoked at view time — output is committed to git as
// client/js/vendor/wc3v-parser.bundle.js.
//
// On parser source changes (lib/, helpers/, wc3v.js), regenerate and commit
// the bundle alongside the source change.

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
const ENTRY = path.resolve(ROOT, 'client/js/parser/parserEntry.js');
const OUTFILE = path.resolve(ROOT, 'client/js/vendor/wc3v-parser.bundle.js');

// helpers/mapResolver.js decides which map a replay was played on. It is
// bundled into the parser above, but pages that only read an already-parsed
// summary still have to answer the same question, and they load plain script
// tags rather than the parser. Copied out verbatim (it has no dependencies)
// so both answers come from one file instead of two that drift — which is the
// bug this whole seam exists to prevent.
const RESOLVER_SRC = path.resolve(ROOT, 'helpers/mapResolver.js');
const RESOLVER_OUT = path.resolve(ROOT, 'client/js/vendor/MapResolver.js');

const SHIM_FS = path.resolve(ROOT, 'client/js/parser/shims/fs-stub.js');
const SHIM_OS = path.resolve(ROOT, 'client/js/parser/shims/os-stub.js');
const SHIM_ZLIB = path.resolve(ROOT, 'client/js/parser/shims/zlib-shim.js');

// Hash the parser sources so the bundle banner records its provenance.
// Lets a future CI check detect a stale bundle without rebuilding.
const hashParserSources = () => {
  const dirs = ['lib', 'helpers', 'config', 'client/js/parser'];
  const files = [];
  const walk = (d) => {
    for (const ent of fs.readdirSync(path.resolve(ROOT, d), { withFileTypes: true })) {
      if (ent.name === 'node_modules' || ent.name.startsWith('.')) continue;
      const full = path.join(d, ent.name);
      if (ent.isDirectory()) walk(full);
      else if (ent.name.endsWith('.js') || ent.name.endsWith('.json')) {
        files.push(full);
      }
    }
  };
  for (const d of dirs) walk(d);
  files.push('wc3v.js');
  files.sort();

  const h = crypto.createHash('sha256');
  for (const f of files) {
    h.update(f);
    h.update(fs.readFileSync(path.resolve(ROOT, f)));
  }
  return h.digest('hex').slice(0, 16);
};

const main = async () => {
  const esbuild = require('esbuild');

  const sourceHash = hashParserSources();
  const banner = [
    '/* wc3v-parser bundle',
    ` * generated by tools/build-parser-bundle.js`,
    ` * source-hash: ${sourceHash}`,
    ` * generated-at: ${new Date().toISOString()}`,
    ' */'
  ].join('\n');

  fs.mkdirSync(path.dirname(OUTFILE), { recursive: true });

  const result = await esbuild.build({
    entryPoints: [ENTRY],
    bundle: true,
    minify: true,
    format: 'iife',
    globalName: 'Wc3vParser',
    target: ['es2020'],
    platform: 'browser',
    alias: {
      fs: SHIM_FS,
      os: SHIM_OS,
      // Browser polyfills for the rest of the Node built-ins the parser
      // closure transitively imports. These are bundled in.
      path: 'path-browserify',
      events: 'events',
      util: 'util',
      zlib: SHIM_ZLIB,
      assert: 'assert',
      // w3gjs uses node: prefixed imports — alias each variant.
      'node:events': 'events',
      'node:zlib': SHIM_ZLIB,
      'node:buffer': 'buffer',
      'node:util': 'util',
      'node:path': 'path-browserify',
      'node:fs': SHIM_FS,
      'node:os': SHIM_OS
    },
    // Make Buffer / process available globally inside the bundle.
    inject: [path.resolve(ROOT, 'client/js/parser/buffer-inject.js')],
    // Define free identifiers that the bundled code references without
    // import. esbuild rewrites these to globalThis-anchored lookups.
    define: {
      'process.env.NODE_ENV': '"production"',
      'global': 'globalThis',
      // Stub __dirname / __filename — only referenced in dead CLI-only
      // codepaths (debug grid output, fs cache writes).
      '__dirname': '""',
      '__filename': '""'
    },
    outfile: OUTFILE,
    // Pre-IIFE polyfill init for free-identifier `process`. Done at the
    // banner so any module-init code that references `process` at load time
    // sees a populated polyfill.
    banner: { js: `${banner}
(function(){
  if(typeof globalThis.process==='undefined'){globalThis.process={env:{NODE_ENV:'production'},platform:'browser',browser:true,version:'',versions:{},nextTick:function(f){queueMicrotask(f);}};}
  // setImmediate polyfill. w3gjs's GameDataParser awaits this between
  // every gamedatablock — typical replay has 60-100k blocks. Three
  // primitives to choose from:
  //   setTimeout(0)    — 4ms browser clamp, makes parse take ~10 minutes
  //   queueMicrotask   — fast, but never yields to the paint frame, so
  //                      progress bar stays frozen until parse completes
  //   MessageChannel   — true macrotask, no clamp; ~0.3ms per yield, but
  //                      80k * 0.3ms = 24s overhead is too much
  // Hybrid: queueMicrotask for most calls, MessageChannel every N to
  // give the browser paint windows without killing throughput.
  if(typeof globalThis.setImmediate==='undefined'){
    var _wc3vYieldEvery=64; var _wc3vYieldCount=0;
    if(typeof MessageChannel!=='undefined'){
      var _wc3vCh=new MessageChannel(); var _wc3vQueue=[];
      _wc3vCh.port2.onmessage=function(){var f=_wc3vQueue.shift(); if(f) f();};
      globalThis.setImmediate=function(f){
        var args=Array.prototype.slice.call(arguments,1);
        _wc3vYieldCount++;
        if(_wc3vYieldCount % _wc3vYieldEvery === 0){
          _wc3vQueue.push(function(){f.apply(null,args);});
          _wc3vCh.port1.postMessage(0);
        } else {
          queueMicrotask(function(){f.apply(null,args);});
        }
        return 0;
      };
    } else {
      globalThis.setImmediate=function(f){var args=Array.prototype.slice.call(arguments,1); queueMicrotask(function(){f.apply(null,args);}); return 0;};
    }
  }
  if(typeof globalThis.clearImmediate==='undefined'){globalThis.clearImmediate=function(){};}
})();
var Wc3vParser = (() => {` },
    footer: { js: '  return Wc3vParser.default || Wc3vParser; })();' },
    metafile: true,
    logLevel: 'info'
  });

  // Wrap the IIFE to expose on window. esbuild's globalName sometimes wraps
  // as `var Wc3vParser = (() => { ... return module.exports; })()` — we
  // override above to make sure `window.Wc3vParser` works.
  // Re-emit a small attach line at the end:
  fs.appendFileSync(OUTFILE, '\nif (typeof window !== "undefined") window.Wc3vParser = Wc3vParser;\n');

  fs.copyFileSync(RESOLVER_SRC, RESOLVER_OUT);

  const stat = fs.statSync(OUTFILE);
  console.log(`\nBundle: ${path.relative(ROOT, OUTFILE)}`);
  console.log(`Size:   ${(stat.size / 1024).toFixed(1)} KB`);
  console.log(`Hash:   ${sourceHash}`);
  console.log(`Copied: ${path.relative(ROOT, RESOLVER_OUT)}`);
};

main().catch(e => {
  console.error('Bundle build failed:', e.message);
  process.exit(1);
});
